export interface Query {
    data:    Data | null;
    errors?: Error[];
}

export interface Data {
    viewer: DataUser;
    pet:    Pet | null;
}

export interface Pet {
    barks?: boolean;
}

export interface DataUser {
    name:    null | string;
    friends: Array<FriendsUser | null> | null;
}

export interface FriendsUser {
    age: number | null;
}

export interface Error {
    message: string;
}

export interface A {
    data:    AData | null;
    errors?: Error[];
}

export interface AData {
    count: number;
}

export interface Error {
    message: string;
}

export interface B {
    data:    BData | null;
    errors?: Error[];
}

export interface BData {
    hello: null | string;
}

